using Microsoft.EntityFrameworkCore;
using DepartmentFinancialRecords.API.Models;
namespace DepartmentFinancialRecords.API.Data;
public sealed class ApplicationDbContext : DbContext
{
 public ApplicationDbContext(DbContextOptions<ApplicationDbContext> options):base(options){}
 public DbSet<Student> Students => Set<Student>(); public DbSet<User> Users=>Set<User>(); public DbSet<AttendanceEvent> AttendanceEvents=>Set<AttendanceEvent>(); public DbSet<AttendanceRecord> AttendanceRecords=>Set<AttendanceRecord>(); public DbSet<Collection> Collections=>Set<Collection>(); public DbSet<Collectible> Collectibles=>Set<Collectible>(); public DbSet<Fine> Fines=>Set<Fine>(); public DbSet<FundTransaction> FundTransactions=>Set<FundTransaction>(); public DbSet<Disbursement> Disbursements=>Set<Disbursement>(); public DbSet<ActivityLog> ActivityLogs=>Set<ActivityLog>();
 protected override void OnModelCreating(ModelBuilder b){b.Entity<Student>().HasIndex(x=>x.StudentId).IsUnique();b.Entity<AttendanceRecord>().HasOne(x=>x.Student).WithMany().HasForeignKey(x=>x.StudentId);b.Entity<AttendanceRecord>().HasOne(x=>x.AttendanceEvent).WithMany().HasForeignKey(x=>x.AttendanceEventId);b.Entity<Collection>().HasOne(x=>x.Student).WithMany().HasForeignKey(x=>x.StudentId);b.Entity<Collectible>().HasOne(x=>x.Student).WithMany().HasForeignKey(x=>x.StudentId);b.Entity<Fine>().HasOne(x=>x.Student).WithMany().HasForeignKey(x=>x.StudentId);b.Entity<ActivityLog>().HasOne(x=>x.User).WithMany().HasForeignKey(x=>x.UserId);}
}
public static class SeedData { public static void Initialize(ApplicationDbContext db){ if(!db.Users.Any()){db.Users.Add(new User{Username="admin",PasswordHash="local-development",Role="Administrator"});} if(!db.Students.Any()){db.Students.AddRange(new Student{StudentId="2026-001",FullName="Mika Reyes",Course="BSIT",YearLevel="3A",Rfid="RFID2026001",Status="Active"},new Student{StudentId="2026-014",FullName="Aaron Cruz",Course="BSCS",YearLevel="2B",Rfid="RFID2026014",Status="Active"},new Student{StudentId="2026-027",FullName="Lia Santos",Course="BSIS",YearLevel="4A",Rfid="RFID2026027",Status="Active"},new Student{StudentId="2026-035",FullName="Noah Dela Cruz",Course="BSIT",YearLevel="1C",Rfid="RFID2026035",Status="Active"});}db.SaveChanges();} }
